import { DeepPartial, IObjectMap } from '../types';

function isDate(x: any): x is Date {
    return Object.prototype.toString.call(x) === '[object Date]';
}

// TODO the ...sources is not nicely typed but works - we need to revisit this later
export function deepMerge<T extends IObjectMap>(destination: T, ...sources: Array<DeepPartial<T>>): T {
    for (let sourceIndex = 0, sourceCount = sources.length; sourceIndex < sourceCount; sourceIndex++) {
        const source = sources[sourceIndex];
        const sourceKeys = Object.keys(source);

        for (let keyIndex = 0, keyCount = sourceKeys.length; keyIndex < keyCount; keyIndex++) {
            const key = sourceKeys[keyIndex];
            const descriptor = Object.getOwnPropertyDescriptor(source, key);

            if (descriptor && (descriptor.get || descriptor.set)) {
                Object.defineProperty(destination, key, descriptor);
            } else {
                const property = source[key];

                if (typeof property === 'function') { // property is a Function
                    destination[key as keyof T] = property;
                } else if (isDate(property)) { // property is a Date
                    destination[key as keyof T] = new Date((property as Date).valueOf()) as T[keyof T];
                } else if (Array.isArray(property)) { // property is an Array
                    destination[key as keyof T] = property as T[keyof T];
                } else if (property !== null && typeof property === 'object' && destination[key]) { // property is an object
                    deepMerge(destination[key], property);
                } else if (property !== null && typeof property === 'object') { // property is an object and doesnt exist on destination
                    Object.assign(destination, { [key]: {} });
                    deepMerge(destination[key], property);
                } else { // property is a simple value
                    destination[key as keyof T] = property as T[keyof T];
                }
            }
        }
    }

    return destination;
}
